Here's a complete, reusable layout component with two variants: `full` and `centered`. It is designed using React and Tailwind CSS and includes optional props for padding, container behavior, and responsiveness.

## 1. Layout Component (`Layout.jsx`)

```jsx
import React from 'react';

const Layout = ({ 
  variant = 'centered', 
  children, 
  padding = 'default', 
  container = true,
  className = ''
}) => {
  const baseClasses = 'min-h-screen w-full';
  const variantClasses = {
    full: 'w-full px-4 sm:px-6 lg:px-8',
    centered: 'w-full px-4 sm:px-6 lg:px-8'
  };

  const getPaddingClasses = () => {
    switch (padding) {
      case 'none':
        return 'py-0';
      case 'small':
        return 'py-4';
      case 'default':
        return 'py-8';
      case 'large':
        return 'py-12';
      case 'xlarge':
        return 'py-16';
      default:
        return 'py-8';
    }
  };

  return (
    <div className={`${baseClasses} ${variantClasses[variant]} ${getPaddingClasses()} ${className}`}>
      {container ? (
        <div className={`mx-auto ${variant === 'centered' ? 'max-w-7xl' : 'max-w-none'}`}>
          {children}
        </div>
      ) : (
        children
      )}
    </div>
  );
};

export default Layout;
